        return 0.0
    return float(sum(len(word) for word in unique_words)) / len(unique_words)

def feature(text: str) -> float:
    "Count of consecutive repeated words in the text"
    words = text.split()
    repeated_count = sum(1 for i in range(1, len(words)) if words[i] == words[i - 1])
    return float(repeated_count)
